final class PreparedSchemaQuery{public function __construct(public string $sql,public array $args){}}
final class FakeWpdb{
 public string $prefix='wp_';public string $last_error='';
 public function get_charset_collate():string{return'DEFAULT CHARACTER SET utf8mb4';}
 public function prepare($q,...$a):PreparedSchemaQuery{return new PreparedSchemaQuery($q,$a);}
 private function cols():array{return[
'id'=>['bigint(20) unsigned','NO'],'idempotency_key'=>['varchar(191)','NO'],'event_type'=>['varchar(64)','NO'],'payload_json'=>['longtext','NO'],'status'=>['varchar(20)','NO'],'attempts'=>['smallint(5) unsigned','NO'],'next_attempt_at'=>['datetime','YES'],'last_http_status'=>['smallint(5) unsigned','YES'],'last_error'=>['varchar(500)','NO'],'last_transport_error'=>['varchar(500)','NO'],'created_at'=>['datetime','NO'],'updated_at'=>['datetime','NO'],'sent_at'=>['datetime','YES'],'dependency_key'=>['varchar(191)','NO'],'lock_token'=>['varchar(64)','NO'],'locked_at'=>['datetime','YES'],'reflection_synced_at'=>['datetime','YES'],'reflection_last_error'=>['varchar(500)','NO'],'reflection_attempts'=>['smallint(5) unsigned','NO'],'reflection_last_attempt_at'=>['datetime','YES']];}
 public function get_var($q){$sql=$q instanceof PreparedSchemaQuery?$q->sql:(string)$q;$a=$q instanceof PreparedSchemaQuery?$q->args:[];if(str_contains($sql,'SHOW TABLES LIKE'))return $GLOBALS['schema_mode']==='missing_table'?null:$this->prefix.'idg_traceability_outbox';if(str_contains($sql,'SELECT idempotency_key'))return $GLOBALS['schema_test_key'];return null;}
 public function get_results($q,$m=null):array{$sql=$q instanceof PreparedSchemaQuery?$q->sql:(string)$q;if(str_contains($sql,'SHOW COLUMNS')){$c=$this->cols();if($GLOBALS['schema_mode']==='partial')unset($c['reflection_last_error']);if($GLOBALS['schema_mode']==='bad_type')$c['payload_json']=['varchar(255)','NO'];return array_map(fn($n,$v)=>['Field'=>$n,'Type'=>$v[0],'Null'=>$v[1]],array_keys($c),array_values($c));}if(str_contains($sql,'SHOW INDEX')){if($GLOBALS['schema_mode']==='missing_index')return[];$defs=[['PRIMARY',0,['id']],['idempotency_key',0,['idempotency_key']],['status_next_attempt',1,['status','next_attempt_at','id']],['dependency_key',1,['dependency_key']],['locked_at',1,['locked_at']],['reflection_sync',1,['reflection_synced_at','updated_at','id']]];$out=[];foreach($defs as[$name,$non,$cols])foreach($cols as$i=>$col)$out[]=['Key_name'=>$name,'Non_unique'=>$non,'Seq_in_index'=>$i+1,'Column_name'=>$col];return$out;}return[];}
 public function query($q){if(!$q instanceof PreparedSchemaQuery)return 0;$sql=$q->sql;$a=$q->args;if(str_starts_with(trim($sql),'INSERT INTO')){if($GLOBALS['schema_mode']==='write_fail'){$this->last_error='write failed';return false;}$GLOBALS['schema_test_key']=(string)$a[0];return 1;}if(str_starts_with(trim($sql),'DELETE FROM')){$GLOBALS['schema_test_key']='';return 1;}return 0;}
}
