$GLOBALS['schema_mode']='complete';$GLOBALS['fail_version_option']=true;unset($GLOBALS['options']['idg_traceability_db_version']);$s=IDG_Traceability_Outbox::install_or_upgrade();ok(empty($s['valid'])&&in_array('schema_version_persistence_failed',$s['errors']??[],true),'fallo al persistir versión mantiene migración incompleta');ok(!isset($GLOBALS['options']['idg_traceability_db_version']),'versión no se declara instalada si update_option falla');
